static void set_slob(slob_t *s, slobidx_t size, slob_t *next) /* <=== set_slob */ 
{
	slob_t *base = (slob_t *)((unsigned long)s & PAGE_MASK);
	slobidx_t offset = next - base;

	if (size > 1) {
		s[0].units = size;
		s[1].units = offset;
	} else
		s[0].units = -offset;
}

static inline size_t strlen(const char *s) /* <=== strlen */ 
{
	register unsigned long r0 asm("0") = 0;
	const char *tmp = s;

	asm volatile(
